mapper.select:
SELECT multiplier_value AS value_json
FROM ()
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND effect_key = #{effectKey}
  AND multiplier_value IS NOT NULL
UNION
SELECT efficiency_value AS value_json
FROM ()
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND effect_key = #{effectKey}
ORDER BY value_json

SELECT formula_key
FROM public.skill_formulas
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}



ORDER BY formula_key
FOR UPDATE

SELECT parameter_key, value_type, value_mode
FROM public.skill_parameters
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}



ORDER BY parameter_key
FOR UPDATE

SELECT effect_key
FROM public.skill_effects
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}



ORDER BY effect_key
FOR UPDATE

SELECT process_key
FROM public.skill_processes
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}



ORDER BY process_key
FOR UPDATE

SELECT step_key
FROM ()
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND process_key = #{processKey}



ORDER BY step_key

SELECT state_key, state_type, scope
FROM public.skill_internal_states
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}



ORDER BY state_key
FOR UPDATE

SELECT option_key
FROM ()
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND state_key = #{stateKey}



ORDER BY option_key

SELECT step_type
FROM ()
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND process_key = #{processKey}
  AND step_key = #{stepKey}

SELECT COUNT(1)
FROM () d
JOIN () b
  ON b.game_id = d.game_id
 AND b.skill_key = d.skill_key
 AND b.effect_key = d.effect_key
 AND b.result_key = d.result_key
WHERE d.game_id = #{gameId}
  AND d.skill_key = #{skillKey}
  AND d.effect_key = #{effectKey}
  AND d.result_key = #{resultKey}
  AND d.status_key = #{statusKey}
  AND d.operation = 'APPLY'
  AND b.moment = 'PERSISTENT'

SELECT lifecycle->>'instanceScope'
FROM public.skill_effects
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND effect_key = #{effectKey}

