FROM ()
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND parameter_key = #{parameterKey}

SELECT
    (SELECT COUNT(1)
     FROM ()
     WHERE game_id = #{gameId}
       AND source_skill_key = #{sourceSkillKey}
       AND skill_key <> #{sourceSkillKey})
  + (SELECT COUNT(1)
     FROM ()
     WHERE game_id = #{gameId}
       AND source_skill_key = #{sourceSkillKey}
       AND skill_key <> #{sourceSkillKey})
